function makeTheme(lang, theme) {
 const src=adventureCopy[lang]?.[theme] ?? adventureCopy.en[theme];
 const ids={modern:[['save','share'],['read','ask'],['shelf','note']],fantasy:[['polish','ask'],['show','team'],['record','oath']],future:[['compare','ask'],['model','robots'],['catalog','light']],jianghu:[['explain','question'],['trace','ask'],['note','post']],loop:[['trace','ask'],['rewind','listen'],['leave','save']]}[theme];
 const tradeoffs=Array.from({length:3},()=>[{cost:{time:1},gain:{favor:2}},{cost:{},gain:{time:1}}]);
 const effects={en:[' This careful route uses 1 time and earns 2 goodwill.',' This quick route costs no resource and leaves 1 extra time for later.'],zh:[' 这条细致路线消耗 1 点时间，换来 2 点人情。',' 这条快捷路线不消耗资源，并为后面多留 1 点时间。'],ja:[' この丁寧な道は時間を1使い、人情を2得ます。',' この手早い道は資源を使わず、後のために時間を1残します。'],es:[' Esta vía cuidadosa usa 1 de tiempo y gana 2 de apoyo.',' Esta vía rápida no cuesta recursos y deja 1 tiempo extra para después.']}[lang]||[];
 const endingRoutes={};
 for(const a of ids[0])for(const b of ids[1])for(const c of ids[2]){
  const path=[a,b,c].join('|');
  let ending;
  if(theme==='modern') ending=a==='save'&&b==='read'&&c==='shelf'?'keeper':a==='share'||b==='ask'?'neighbor':'bridge';
  if(theme==='fantasy') ending=c==='oath'?'oath':a==='polish'&&b==='show'?'record':'witness';
  if(theme==='future') ending=a==='compare'&&b==='model'&&c==='catalog'?'catalog':a==='compare'&&b==='model'?'signal':'gathering';
  if(theme==='jianghu') ending=c==='note'?'note':a==='explain'&&b==='trace'?'truth':'ally';
  if(theme==='loop') ending=c==='save'?'anchor':a==='trace'&&b==='rewind'?'reset':'ripple';
  endingRoutes[path]=ending;
 }
 return {...src, endingRoutes, scenes:src.scenes.map((scene,si)=>({...scene, choices:scene.choices.map(([_,label,__ ,feedback],ci)=>({id:ids[si][ci],label,cost:tradeoffs[si][ci].cost,gain:tradeoffs[si][ci].gain,feedback:feedback+effects[ci]}))}))};
}
export function adventureContent(lang) { return Object.fromEntries(Object.keys(adventureCopy.zh).map(theme=>[theme,makeTheme(lang,theme)])); }
export function resourceEffect(lang, choice) {
 const names={en:{time:'time',favor:'goodwill'},zh:{time:'时间',favor:'人情'},ja:{time:'時間',favor:'人情'},es:{time:'tiempo',favor:'apoyo'}}[lang]||{time:'time',favor:'goodwill'};
 const parts=[];for(const [key,label] of Object.entries(names)){const cost=Number(choice.cost?.[key]||0),gain=Number(choice.gain?.[key]||0);if(cost)parts.push(`−${cost} ${label}`);if(gain)parts.push(`+${gain} ${label}`);}return parts.join(' · ')||gameText(lang,'life','free');
}

