export function debugRoomContent(lang) { return debugCopy[lang] ?? debugCopy.en; }
export function debugRoomLevelCount() { return debugCopy.en.length; }
export function debugCommit(lang, wrong) {
 const c=key=>gameText(lang,'debug',key);
 const levels=debugRoomContent(lang);
 const subject=wrong===0?c('verdictPerfect'):wrong<=2?c('verdictGood'):c('verdictSlow');
 const body=levels.map(level=>`- ${level.commitLine}`).join('\n');
 return `${c('commitPrefix')}${subject}\n\n${body}\n\n${c('commitTrailer')}`;
}
